{{(() => {
  const r = GetCodReport.data;
  if (!r || !r.totals) return 'Изберете период.';
  const t = r.totals;
  const who = MerchantSelect.selectedOptionValue && MerchantSelect.selectedOptionValue !== 'all' ? (MerchantSelect.selectedOptionLabel || '') : 'всички клиенти';
  const e = (n) => (Number(n) || 0).toFixed(2) + ' €';
  return `Период ${r.period.label} · ${who} · ${t.orders} поръчки\nГрупа А — Наложен платеж: ${e(t.total)} (в брой ${e(t.cash)}, с карта ${e(t.card)})\nГрупа Б — Приходи: ${e(t.revenue)} (в брой ${e(t.revenue_cash)}, с карта ${e(t.revenue_card)}) — доставки ${e(t.delivery)} + такса НП ${e(t.fee)}`;
})()}}
